import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BfI5QxtK.js";const f=JSON.parse('{"title":"Gnoblin","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),i={name:"README.md"};function n(l,e,s,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="gnoblin" tabindex="-1">Gnoblin <a class="header-anchor" href="#gnoblin" aria-label="Permalink to &quot;Gnoblin&quot;">​</a></h1><p>Gnoblin is the floating window manager and desktop tooling you can build a Wayland desktop on. It manages windows, workspaces, input and desktop services; you choose the bar, dock, launcher and other visible shell components. A regular GNOME login remains available separately.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li><a href="./installation">Install Gnoblin</a>.</li><li><a href="./bring-your-own-shell">Choose a shell</a>.</li><li><a href="./configuration">Configure your desktop</a>.</li><li><a href="./build-a-desktop">Build a desktop from Gnoblin&#39;s primitives</a>.</li></ol><h2 id="make-it-yours" tabindex="-1">Make it yours <a class="header-anchor" href="#make-it-yours" aria-label="Permalink to &quot;Make it yours&quot;">​</a></h2><ul><li><a href="./shortcuts">Shortcuts</a> — launch commands and change keys.</li><li><a href="./window-rules">Window rules</a> — choose which windows a setting affects.</li><li><a href="./window-effects">Effects</a> — blur, corners, borders and shadows.</li><li><a href="./window-frames">Titlebars</a> — client and server decorations.</li><li><a href="./animations">Animations</a> — timing and motion.</li><li><a href="./configuration-reference">All settings</a> — find an option.</li></ul><h2 id="build-a-shell-or-integration" tabindex="-1">Build a shell or integration <a class="header-anchor" href="#build-a-shell-or-integration" aria-label="Permalink to &quot;Build a shell or integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Start here</th></tr></thead><tbody><tr><td>Read and control windows from a program</td><td><a href="./gnoblinctl">gnoblinctl</a> or the <a href="./compositor-bridge">compositor bridge</a></td></tr><tr><td>Wire up a bar, dock or launcher</td><td><a href="./shell-integration">Shell integration</a> and <a href="./bridge-examples">bridge examples</a></td></tr><tr><td>Use a Wayland client protocol</td><td><a href="./wayland-protocols">Protocol catalog</a></td></tr><tr><td>React inside GNOME Shell</td><td><a href="./user-scripts">User scripts</a></td></tr><tr><td>Choose which application gets an effect</td><td><a href="./window-rules">Window rules</a></td></tr></tbody></table><p>Gnoblin owns the compositor interfaces. Bingux is one independent project that uses them; the same interfaces are available to your shell.</p><h2 id="need-help" tabindex="-1">Need help? <a class="header-anchor" href="#need-help" aria-label="Permalink to &quot;Need help?&quot;">​</a></h2><p>Start with <a href="./troubleshooting">troubleshooting</a>. For custom automation, see <a href="./user-scripts">user scripts</a>. Shells use the built-in <a href="./compositor-bridge">compositor bridge</a> and can use <a href="./gnoblinctl">gnoblinctl</a>.</p>',11)])])}const p=a(i,[["render",n]]);export{f as __pageData,p as default};
